mapper.select:
select ia.id, ia.name, sd.item_text as isCoreName, sdi.item_text as competitiveTypeName, ia.status, sd1.item_text as statusName, ia.update_operator as operator, ia.create_time, ia.update_time from ins_automark ia left join (select sdi.item_text,sdi.item_value from ins_dict sd left join ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'competitive_type' ) sdi on sdi.item_value = ia.competitive_type left join (select sdi.item_text,sdi.item_value from ins_dict sd left join ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'is_core' ) sd on sd.item_value = ia.is_core left join (select sdi.item_text,sdi.item_value from ins_dict sd left join ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'enable_type' ) sd1 on sd1.item_value = ia.status where 1=1
and ia.name like concat('%', #{model.name}, '%')
and ia.is_core =#{model.isCore}
and ia.competitive_type = #{model.competitiveType}
and ia.status = #{model.status}
and ia.operator like concat('%', #{model.operator}, '%')
order by ia.${model.order}
order by ia.competitive_type asc,ia.is_core desc
